export const records = [{"schema_version":1,"id":"AUT-0461","slug":"sales-commission-reversal-after-return-credit-memo","title":"Перерахунок комісії продавця після повернення чи скасування продажу","summary":"Повернення, кредит-ноту або скасування продажу пов’язують із початковою комісією та перераховують її за затвердженим планом винагороди.","problem":"Продаж уже нарахував комісію, але пізніше клієнту повернули частину суми або кредитували рахунок. Без зв’язку з первинною комісією компанія може повторно нарахувати винагороду, зменшити її не за тим правилом або безпідставно утримати суму з уже виплаченої зарплати.","outcome":"Кожна зміна продажу має перевірений зв’язок із первинною комісією, сумою перерахунку, правилом плану й затвердженим обліковим результатом.","category":"finance","subcategory":"payments","roles":["finance-specialist","sales-manager","operations-manager"],"industries":["wholesale","retail","professional-services"],"triggers":["Після нарахування комісії в обліку проведено повернення, часткове скасування продажу або кредит-ноту."],"workflow_steps":["Отримати проведену подію повернення чи кредитування з ідентифікаторами клієнта, документа, рядка продажу, суми й дати.","Зіставити її з первинним замовленням, рахунком та рядками комісії; неповний або неоднозначний зв’язок передати на ручну звірку.","Визначити початковий план винагороди, правило нарахування, продавця, період і статус виплати на дату первинного продажу.","Перерахувати тільки частину комісії, на яку впливає проведена подія; часткове повернення не скасовує всю комісію автоматично.","Перевірити попередні коригування за унікальним ID події, щоб повторна доставка повідомлення не створила друге списання.","Показати джерельні документи, початкове нарахування, від’ємну або іншу коригувальну суму та правило розрахунку менеджеру й фінансисту.","Після затвердження передати коригування в систему комісій або розрахунку винагород і повторно прочитати збережений результат.","Якщо первинна комісія вже виплачена, створити окремий випадок для погодженого майбутнього розрахунку; не утримувати гроші із зарплати без перевіреної політики та правової підстави."],"requirements":["Збережено стабільні посилання між поверненням або кредит-нотою, первинним продажем і розрахованою комісією.","План винагороди визначає обробку часткових повернень, дати чинності правил і коригувань після виплати.","Відомо, хто погоджує суму та як передати коригування до системи комісій або payroll."],"limitations":["Різні плани визначають момент і суму зміни комісії по-різному; приклади Oracle та NetSuite не є правилом для кожного клієнта.","Кредит-нота не завжди означає фактичне повернення грошей клієнту; умови виплати комісії потрібно перевіряти окремо.","Картка не визначає законність відрахувань із заробітної плати. Такі дії потребують окремої перевірки політики й місцевих вимог.","Години попередні; якість зіставлення даних, кількість планів винагород і статус попередніх виплат уточнюють під час аудиту."],"problems":["як перерахувати комісію менеджера якщо клієнту повернули гроші за замовлення","як не платити комісію вдруге за скасований продаж","кредит нота після нарахування комісії продавцю"],"synonyms":["commission reversal","sales commission clawback","credit memo commission adjustment","коригування комісії за повернення"],"search_queries":["як звірити кредит-ноту з раніше нарахованою комісією продавця","як перерахувати часткове повернення в плані продажних винагород"],"sources":[{"type":"vendor_documentation","title":"NetSuite: Commission and Credit Memos","url":"https://docs.oracle.com/en/cloud/saas/netsuite/ns-online-help/section_3720939620.html","checked_at":"2026-10-09","supports":"Описує від’ємну комісію за кредит-нотою та різну поведінку clawback залежно від плану: billing-based чи cash-collection-based і повернення грошей клієнту."},{"type":"vendor_documentation","title":"Oracle Incentive Compensation User Guide: Receivables events and order adjustments","url":"https://docs.oracle.com/cd/E26401_01/doc.122/e49154/T300492T300502.htm","checked_at":"2026-10-09","supports":"Документує кредит-ноти й повернення як події розрахунку винагород; змінений рядок продажу може створити від’ємну реверсну транзакцію для вже завантаженої комісії."},{"type":"vendor_documentation","title":"Oracle Order Management: Manage Channel Programs on Sales Orders","url":"https://docs.oracle.com/en/cloud/saas/supply-chain-and-manufacturing/26a/fauom/manage-channel-programs-on-sales-orders.html","checked_at":"2026-10-09","supports":"Підтверджує, що при поверненні з посиланням на початковий рядок система копіює й реверсує його incentive; не описує комісію продавця."},{"type":"inferred_pattern","title":"Редакційний процес контрольованого перерахунку комісії","supports":"Ідемпотентність, ручне погодження та межі інтеграції є проєктними вимогами картки; години не підтверджені клієнтським впровадженням."}],"status":"draft","variants":[{"id":"commission-return-review-tracked","title":"Ручна перевірка коригування комісії","description":"Фінансист перевіряє джерельні документи, формулу плану й статус виплати та передає погоджене коригування відповідальному фахівцю.","best_for":["Компаній із небагатьма поверненнями та розрахунком комісії у таблиці або системі без потрібного API."],"example":"За продаж із комісією 500 USD провели кредит-ноту на 20% вартості. За правилом плану фінансист розрахував коригування 100 USD, звірив попередню виплату й передав його на погодження.","implementation_methods":["Пов’язати документ повернення з продажем і рядком розрахунку комісії.","Зберігати тип події, формулу, суму та погодження окремим записом.","Після внесення коригування звірити його з реєстром комісій."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Доступні документи повернення, первинний продаж і чинний план винагороди."],"limitations":["Масове зіставлення та автоматична передача коригувань не входять до варіанта."],"pricing_modifiers":[]},{"id":"commission-return-integrated","title":"Подієве зіставлення та передача коригування","description":"Перевірений інтеграційний процес знаходить первинну комісію за ID повернення, обчислює дозволений вплив і передає винятки на погодження.","best_for":["Системи комісій і продажів мають API або надійний експорт з незмінними ID подій."],"example":"Система отримала кредит-ноту 200 USD, знайшла рядок продажу й продавця, застосувала правило чинного плану, створила коригування комісії та не повторила його після повторної доставки події.","implementation_methods":["Читати проведені повернення, кредит-ноти, рядки продажу, продавця та збережені комісії.","Версіонувати таблицю правил із датами чинності й обмежувати суму первинною комісією.","Записувати коригування після погодження, перечитувати результат і зберігати ID транзакції."],"complexity":"high","hours_min":48,"hours_max":96,"requirements":["Підтверджені API або стабільний експорт, документація планів комісії та тестовий контур."],"limitations":["Утримання вже виплаченої комісії не автоматизується без окремо затвердженої політики й перевірки права."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0058","reason":"Картка повернень керує товаром і рішенням про обмін. Ця картка перераховує комісію за проведеним фінансовим коригуванням продажу."},{"type":"related","target_id":"AUT-0200","reason":"Картка повернення коштів контролює погоджене відшкодування клієнту; ця картка змінює винагороду продавця за правилами комісійного плану."},{"type":"related","target_id":"AUT-0404","reason":"Розподіл комісії платежу визначає одержувачів комісійних зборів за транзакцією. Ця картка коригує sales commission через подальше повернення або credit memo."}],"configurator_questions":[{"id":"commission-return-multiple-credit-lines","question":"Чи потрібно коригувати комісію кільком продавцям або сплітам одного продажу?","help_text":"Вкажіть правило розподілу початкової комісії та власника кожної частини.","type":"boolean","required":true,"options":[],"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Додається пошук усіх одержувачів і збереження розподілу первинної комісії."}]},{"id":"commission-return-already-paid","question":"Чи можуть повернення стосуватися комісії, яку вже виплатили?","help_text":"Потрібні погоджені правила обліку відповідальності й спосіб коригування майбутньої винагороди.","type":"boolean","required":true,"options":[],"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Додається окремий маршрут залишку без автоматичного payroll-відрахування."}]}]},{"schema_version":1,"id":"AUT-0462","slug":"employee-role-change-access-transition-review","title":"Перегляд доступів після зміни посади або відділу","summary":"Зміна ролі працівника запускає перевірку старих і потрібних нових доступів із погодженим переходом та підтвердженням результату.","problem":"Працівника переводять до іншого відділу або змінюють його посаду. Нові права додають за запитом менеджера, але старі доступи часто залишаються активними, а власники систем не бачать повної зміни ролі.","outcome":"Для кожної кадрової зміни визначені старі права, схвалені нові права, дата переходу, власники систем і перевірений результат відкликання та надання доступів.","category":"hr","subcategory":"workforce","roles":["hr-specialist","operations-manager","owner"],"industries":["professional-services","manufacturing","retail"],"triggers":["У кадровому джерелі змінилася посада, відділ або керівник працівника."],"workflow_steps":["Отримати підтверджену кадрову подію з ідентифікатором працівника, старою та новою посадою, підрозділом, керівником і датою чинності.","Перевірити попередній і новий профілі доступу за каталогом ролей; невідомі або надмірно широкі призначення передати власнику ресурсу.","Скласти перелік прав до відкликання, нових прав на погодження та дозволених тимчасових винятків для передавання роботи.","Надіслати рішення керівнику й власникам відповідних систем; несумісні ролі або конфлікти обов’язків ескалювати окремому погоджувачу.","Запланувати зміну на дату переходу: старі права відкликати у погоджений строк, нові надати після потрібних погоджень.","Для перехідного доступу встановити власника й дату автоматичного завершення; відсутність відповіді не продовжує права.","Передати затверджені зміни до перевірених систем або виконавцям, зберігаючи окремий статус для кожного застосунку й групи.","Повторно прочитати поточні призначення, порівняти їх із погодженим набором і залишити невиконані відкликання відкритими винятками.","Зберегти кадрову подію, версію профілю, рішення погоджувачів, виконавців, часові мітки й результат для аудиту."],"requirements":["Кадрове джерело передає достовірні зміни ролі та дату набрання ними чинності.","Є погоджений каталог профілів доступу, власників систем і матриця несумісних повноважень.","Визначені правила строків відкликання, тимчасового доступу, винятків і підтвердження фактичного стану систем."],"limitations":["Кадрова зміна не доводить, що нові права вже погоджені або що всі системи підтримують автоматичне відкликання.","Профілі доступу, матрицю несумісних обов’язків і винятки потрібно затвердити для кожного клієнта.","Картка охоплює подію зміни ролі; планові перегляди доступів і вихід працівника залишаються окремими процесами.","Ліцензії Microsoft Entra, доступність задач і затримки обробки залежать від цільової конфігурації та плану підписки.","Години попередні; джерела кадрових подій, кількість застосунків та інтерфейси відкликання уточнюють після аудиту."],"problems":["як перевірити доступи коли працівника переводять в інший відділ","як забрати старі права і видати нові після зміни посади","переведення працівника залишає доступ до систем попереднього відділу"],"synonyms":["employee mover access review","job change access transition","role change provisioning","переведення працівника","зміна посадових доступів"],"search_queries":["як прибрати доступ до старих систем після переведення співробітника","як видати потрібні групи коли змінився відділ працівника"],"sources":[{"type":"vendor_documentation","title":"Microsoft Entra: What are lifecycle workflows?","url":"https://learn.microsoft.com/en-us/entra/id-governance/what-are-lifecycle-workflows","checked_at":"2026-10-09","supports":"Визначає mover як окрему подію життєвого циклу працівника та описує доступи, групи, автоматизовані дії й журнал запусків."},{"type":"vendor_documentation","title":"Microsoft Entra: Automate employee mover tasks when they change jobs","url":"https://learn.microsoft.com/en-us/entra/id-governance/tutorial-mover-custom-workflow-portal","checked_at":"2026-10-09","supports":"Показує запуск workflow за зміною department, повідомлення керівника, відкладене зняття пакетних доступів і додавання до нової групи."},{"type":"vendor_documentation","title":"Microsoft Entra: Assign employee access deployment guide","url":"https://learn.microsoft.com/en-us/entra/architecture/governance-deployment-employee-access","checked_at":"2026-10-09","supports":"Описує рольові правила надання й відкликання пакетів доступу, погодження, перевірки доступу та окремі правила несумісних повноважень."},{"type":"inferred_pattern","title":"Редакційний сценарій переходу між профілями доступу","supports":"Порівняння старого й нового набору, контроль винятків і трудомісткість є проєктною моделлю; впровадження конкретного клієнта не перевірене."}],"status":"draft","variants":[{"id":"employee-mover-access-review-tracked","title":"Погодження і ручне підтвердження змін","description":"Кадрова подія формує перелік старих і нових прав; менеджери погоджують його, а адміністратор фіксує виконання по системах.","best_for":["Невеликої кількості переведень і систем без стабільних API для зміни груп."],"example":"Працівника переводять із закупівель до продажів. Керівники погодили нову групу CRM, відкликання доступу до закупівель та тимчасове право читання на 5 днів для передачі справ.","implementation_methods":["Зафіксувати зміну кадрових атрибутів і дату набрання чинності.","Порівняти матриці доступу старої та нової ролі й погодити відмінності.","Виконати й перевірити зміни у кожній системі окремо."],"complexity":"medium","hours_min":18,"hours_max":36,"requirements":["Є власник кадрової події, каталог профілів доступу та відповідальні за системи."],"limitations":["Відкликання, надання й повторна перевірка лишаються ручними."],"pricing_modifiers":[]},{"id":"employee-mover-access-integrated","title":"Подієва синхронізація профілів доступу","description":"Перевірені конектори застосовують затверджені зміни до груп та пакетів доступу, фіксують результат і створюють задачі для систем без API.","best_for":["Кадрова система та основні каталоги ідентичностей мають перевірені API або журнали синхронізації."],"example":"Подія зміни підрозділу запустила перевірку профілів, зняла дві старі групи в дату переходу, додала погоджену групу продажів і залишила одну систему відкритим винятком для адміністратора.","implementation_methods":["Читати кадрові зміни з унікальним ID і підтримувати повторну доставку без дубльованих дій.","Обчислювати різницю між погодженими старими й новими профілями доступу.","Застосовувати, перечитувати й журналювати зміну кожного доступу окремо."],"complexity":"high","hours_min":42,"hours_max":84,"requirements":["Перевірені API, тестовий контур і призначені власники профілів доступу."],"limitations":["Системи без API потребують контрольованої ручної задачі; не можна вважати відсутність відповіді погодженням."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0086","reason":"Регулярний перегляд доступів шукає надлишкові права загалом. Ця картка запускається саме від кадрової зміни й порівнює старий та новий профілі."},{"type":"related","target_id":"AUT-0079","reason":"Завершення роботи працівника закриває доступи під час виходу. Ця картка обробляє переведення, коли працівник залишається в організації."},{"type":"related","target_id":"AUT-0042","reason":"Адаптація нового співробітника готує його до роботи. Ця картка змінює доступи чинного працівника при зміні посади чи підрозділу."}],"configurator_questions":[{"id":"employee-mover-access-multiple-systems","question":"Чи потрібно змінювати доступи більш ніж у трьох системах?","help_text":"Вкажіть системи, власників і спосіб підтвердження фактичних змін.","type":"boolean","required":true,"options":[],"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Додаються конектори або окремі контрольовані маршрути для додаткових систем."}]},{"id":"employee-mover-access-temporary-overlap","question":"Чи потрібні тимчасові старі доступи для передачі роботи?","help_text":"Потрібні власник винятку, дозволений обсяг прав і точна дата завершення.","type":"boolean","required":true,"options":[],"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Додається погоджений виняток із датою завершення та перевіркою автоматичного відкликання."}]}]},{"schema_version":1,"id":"AUT-0463","slug":"workplace-near-miss-investigation-and-prevention","title":"Розбір небезпечної події без травмування","summary":"Повідомлення про подію без шкоди запускає перевірку небезпек, погодження запобіжних дій і контроль їх результату.","problem":"Працівники не повідомляють про небезпечні ситуації або повідомлення губляться. Команда не пов’язує повторні випадки й не перевіряє, чи усунули причину до наступної події.","outcome":"Кожна повідомлена подія має зафіксовані факти, рішення про термінові запобіжні дії, висновок відповідальних і перевірений результат погоджених заходів.","category":"security-compliance","subcategory":"audit","roles":["operations-manager","technician","owner"],"industries":["manufacturing","construction","logistics","cross-industry"],"triggers":["Працівник повідомив про небезпечну умову або подію, яка могла спричинити травму, пошкодження чи іншу шкоду, але шкоди не сталося."],"workflow_steps":["Негайну небезпеку передати відповідальному для усунення за чинним порядком. Реєстрація повідомлення не затримує захист людей чи обладнання.","Зафіксувати час, місце, джерело, опис без припущень і доступні докази. Повторні повідомлення зв’язати з подією, не стираючи відмінності у свідченнях.","Визначити, чи це справді подія без шкоди. Якщо з'явились відомості про травму, захворювання або обов’язкове повідомлення, передати випадок до окремої процедури.","Відповідальний класифікує небезпеку, визначає потрібних учасників розбору й тимчасові обмеження. Невідомі факти залишити непідтвердженими.","Разом із працівниками встановити безпосередні й системні чинники. Не закривати аналіз формулюванням про помилку людини без перевірки умов роботи, обладнання, інструкцій і навчання.","Погодити запобіжні дії, власників, строки й спостережувані критерії виконання. Розділити негайне стримування ризику та довгострокову зміну.","Прийняти докази виконання й окремо перевірити, чи діє новий контроль у роботі. Неефективні дії повернути на перегляд із причиною.","Повідомити працівникам висновки й застосовні зміни, не розкриваючи зайвих персональних даних. Переглядати повторювані типи небезпек за майданчиком і процесом, а не ранжувати людей."],"requirements":["Є відповідальний за охорону праці, порядок реагування на безпосередню небезпеку та критерії ескалації випадків зі шкодою.","Погоджені формат повідомлення, доступ до доказів, участь працівників і правила приватності.","Для запобіжних дій визначені власники, строки, докази завершення й спосіб перевірки результативності."],"limitations":["Це маршрут координації події без травмування. Реальне травмування або інша шкода потребує окремої процедури, допомоги та визначення належних повідомлень.","Закони, строки зовнішнього звітування й обов’язки роботодавця не визначаються матеріалами OSHA чи HSE; їх уточнює компетентний фахівець за місцем роботи.","Не можна робити висновок про вину, безпечність робочого місця чи достатність заходів лише на підставі заповненої форми.","Анонімний канал, доступ до свідчень і строки зберігання налаштовують за політикою організації та застосовними вимогами.","PlanFix може координувати записи, відповідальних, статуси та задачі; фізичні дії й спеціалізовані оцінки виконує уповноважена команда.","Години попередні; аудит вимог, фахове розслідування та впровадження фізичних засобів контролю не включені."],"problems":["як фіксувати небезпечні випадки без травм і перевіряти що зробили","працівник ледь не травмувався але незрозуміло як розібрати причину","повторюються небезпечні ситуації на виробництві а дії ніхто не перевіряє"],"synonyms":["near miss","near-miss reporting","повідомлення про подію без шкоди","небезпечне зближення"],"search_queries":["як розбирати небезпечну подію якщо ніхто не постраждав","як пов’язати повторні повідомлення про небезпеку та перевірити запобіжні дії"],"sources":[{"type":"vendor_documentation","title":"OSHA: Incident Investigation","url":"https://www.osha.gov/incident-investigation","checked_at":"2026-10-09","supports":"Рекомендація досліджувати події без травми, шукати небезпеки й системні причини та залучати працівників разом із керівниками. Це методична сторінка США, не норма українського права й не готова конфігурація."},{"type":"vendor_documentation","title":"HSE: Near-miss Book — Recording and reporting near misses at work","url":"https://www.hse.gov.uk/PUBNS/near-miss-book.htm","checked_at":"2026-10-09","supports":"HSE описує запис і аналіз таких повідомлень для пошуку повторюваних умов та раннього реагування. Публікація 2021 року не встановлює вимоги для України."},{"type":"vendor_documentation","title":"PlanFix: Tasks","url":"https://planfix.com/help/Tasks","checked_at":"2026-10-09","supports":"Задачі PlanFix можуть мати типи, поля, статуси й сценарії; це підтверджує можливість координувати записи та відповідальних, але не спеціалізоване розслідування чи фізичне усунення небезпеки."},{"type":"inferred_pattern","title":"Редакційна модель розбору подій без шкоди","supports":"Зв’язування повторів, розділення фактів і висновків, перевірка результату дій, питання, години та варіанти — проєктна модель для аудиту."}],"status":"draft","variants":[{"id":"near-miss-managed-review","title":"Керований розбір і контроль дій","description":"Відповідальна команда приймає повідомлення, документує аналіз і перевіряє запобіжні дії у погоджених задачах.","best_for":["Одна команда або майданчик із визначеним відповідальним і помірним потоком повідомлень."],"example":"Працівник повідомив про падіння коробки поруч із проходом без травми. Керівник локально огородив ділянку, команда зв'язала два схожі повідомлення й виявила нестабільне штабелювання. Після зміни правила зберігання відповідальний перевірив наступні обходи й додав доказ до тієї самої справи.","requirements":["Є захищене місце для повідомлень і власник перевірки кожної погодженої дії."],"implementation_methods":["Налаштувати тип задачі PlanFix з обмеженими полями, статусами, відповідальними та підзадачами для запобіжних дій.","Для повторів зберігати зв’язок із джерельними повідомленнями й не перезаписувати свідчення.","Вести рішення фахівця й докази перевірки результату окремими полями або пов'язаними задачами."],"complexity":"medium","hours_min":18,"hours_max":36,"pricing_modifiers":[],"limitations":["Автоматичне подання зовнішніх звітів і технічне усунення небезпеки не входять до цього варіанта."]},{"id":"near-miss-integrated-intake-and-trends","title":"Інтегрований збір і аналіз повторів","description":"Повідомлення з погоджених каналів створюють пов'язані справи; звіти показують повторювані типи небезпек і невиконані дії.","best_for":["Кілька майданчиків або значний потік повідомлень із затвердженими каналами збору та аналітики."],"example":"Форми з двох майданчиків передали повідомлення з унікальними номерами. Система об'єднала ймовірний повтор як пов'язаний випадок, але не видалила первинні записи; звіт показав одну незавершену дію та повтори навколо тієї самої операції.","requirements":["Визначені дозволені системи надходження, правила ідентифікації повторів, ролі доступу й актуальні довідники майданчиків."],"implementation_methods":["Імпортувати повідомлення з погоджених форм через перевірений API чи інтеграційний шлюз із захистом від повторного запису.","Відображати тенденції за типом небезпеки, процесом, майданчиком і статусом дії з урахуванням обмежень доступу.","Окремо зберігати первинні свідчення, рішення, версію класифікації та перевірку результативності."],"complexity":"high","hours_min":34,"hours_max":68,"pricing_modifiers":[],"limitations":["Якість групування повторів залежить від довідників і підтвердження відповідального; автоматичний збіг не встановлює однакову причину."]}],"dependencies":[{"type":"related","target_id":"AUT-0280","reason":"AUT-0280 координує справу після травмування; ця картка фіксує події без шкоди як окремий превентивний маршрут."},{"type":"related","target_id":"AUT-0281","reason":"Передавання зміни повідомляє наступну команду про відкриті роботи; розбір події встановлює причини й запобіжні дії."},{"type":"related","target_id":"AUT-0122","reason":"Перевірка коригувальної дії може підтвердити результат конкретного заходу; ця картка веде повний маршрут повідомлення про небезпечну подію без шкоди."}],"configurator_questions":[{"id":"near-miss-multiple-sites","question":"Чи потрібно вести повідомлення для кількох майданчиків?","help_text":"Уточніть окремих відповідальних, довідники локацій, доступ до деталей і спільну звітність.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Налаштувати маршрути, ролі та звіти за кількома майданчиками."}]},{"id":"near-miss-source-integration","question":"Чи потрібно автоматично приймати повідомлення із зовнішніх каналів?","help_text":"Погодьте джерело, захищені поля, ID повідомлення та поведінку при повторному надсиланні.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Додати погоджене джерело, інтеграцію, захист від повторів і перевірку доставки."}]}]},{"schema_version":1,"id":"AUT-0464","slug":"emergency-admin-access-validation-and-use-review","title":"Перевірка аварійного доступу адміністратора","summary":"Команда регулярно перевіряє працездатність резервного доступу та розбирає кожне його використання.","problem":"Резервний обліковий запис адміністратора створили на випадок відмови звичайного входу, але ніхто не перевіряє, чи він працює і чи сповіщення про використання доходить до команди.","outcome":"Для кожного аварійного облікового запису є актуальний список уповноважених, дата й результат погодженої перевірки, підтвердження сигналу моніторингу та окрема перевірка кожного реального використання.","category":"security-compliance","subcategory":"access","roles":["owner","operations-manager","technician"],"industries":["it-saas","professional-services","cross-industry"],"triggers":["Настав строк погодженого навчального тесту аварійного доступу або система моніторингу повідомила про його використання."],"workflow_steps":["Визначити облікові записи, власника контролю, уповноважених користувачів, джерело журналів та процедуру відновлення доступу.","До навчального тесту повідомити команду моніторингу про погоджений час і перевірити, що тест не буде сприйнятий як непогоджений інцидент.","Уповноважений адміністратор за затвердженою процедурою перевіряє вхід і потрібну контрольну дію. Система координації не зберігає секрети й не входить під привілейованим записом.","Перевірити фактичне отримання сигналу моніторингу, його одержувачів, часові мітки та зв'язок із запланованим тестом; пропущене сповіщення залишити відкритим винятком.","Оновити список уповноважених, підтвердити доступність захищеного способу отримання облікових даних і переглянути зміни в команді чи політиці входу.","Кожний позаплановий сигнал створює окремий терміновий випадок для відповідального. Він зберігає посилання на журнали, з'ясовує підставу та перевіряє виконані адміністративні дії.","Погодити результат: санкціоноване використання, навчальний тест або невирішена подія; невідомий користувач чи неповний журнал потребує ескалації.","За рішенням відповідального оновити процедуру, контроль або спосіб зберігання секретів. Не закривати випадок тільки тому, що доступ згодом відновили.","Зберігати дату, учасників, результат і посилання на журнал за погодженим строком; не копіювати пароль, ключ чи код другого фактора до задачі або сповіщення."],"requirements":["Є документована аварійна процедура, окремо визначені уповноважені й захищене місце зберігання облікових даних.","Погоджені строк тестування, безпечна контрольна дія, спосіб попередження моніторингу та критерії успіху.","Доступні журнали входу й аудиту або призначений відповідальний, який перевіряє їх у джерельній системі.","Визначені терміновість сповіщення, ескалація невідомого використання та правила збереження доказів."],"limitations":["Microsoft радить щонайменше два аварійні облікові записи та перевірку не рідше ніж раз на 90 днів для Microsoft Entra; це рекомендація вендора для його середовища, не універсальна норма.","Не створює резервні облікові записи, не змінює політики автентифікації й не виконує тестовий вхід замість уповноваженого адміністратора.","Не зберігає паролі, секрети, коди MFA чи особисті пристрої; матеріали моніторингу залишаються у джерельній системі з її правами доступу.","Сповіщення не доводить, що всі журнали повні або що використання було безпечним; людина перевіряє події та адміністративні дії.","PlanFix може координувати графік, відповідальних, винятки та посилання на докази; робота з обліковим записом і журнали потребують окремої системи ідентичності та моніторингу.","Години попередні; налаштування IAM, моніторингу, безпечного сховища та відновлення доступу не включені."],"problems":["як перевіряти аварійний доступ адміністратора і сповіщення про його використання","резервний адмін акаунт може не працювати коли заблоковані звичайні входи","хто перевіряє аварійний обліковий запис та розбирає його використання"],"synonyms":["emergency access account","break-glass account","аварійний обліковий запис","резервний доступ адміністратора"],"search_queries":["як регулярно перевіряти аварійний доступ адміністратора та сповіщення про його використання","як розібрати вхід у резервний обліковий запис адміністратора"],"sources":[{"type":"vendor_documentation","title":"Microsoft Entra: Manage emergency access accounts","url":"https://learn.microsoft.com/en-us/entra/identity/role-based-access-control/security-emergency-access","checked_at":"2026-10-09","supports":"Вимагає документовану процедуру, моніторинг кожного входу, регулярну перевірку працездатності й післяподієвий розбір. Microsoft наводить власні вимоги для Entra, включно з інтервалом до 90 днів; вони не переносяться автоматично на інші продукти чи юрисдикції."},{"type":"vendor_documentation","title":"PlanFix: Tasks","url":"https://planfix.com/help/Tasks","checked_at":"2026-10-09","supports":"Тип задачі може містити поля й статуси та використовувати сценарії; це дає основу для координації перевірок і винятків, але не підтверджує читання журналів IAM або зберігання секретів у PlanFix."},{"type":"inferred_pattern","title":"Редакційна модель перевірки аварійного доступу","supports":"Пов'язування планового тесту з окремим інцидентом, контроль сповіщень, критерії перевірки, питання та оцінка є проєктною моделлю для аудиту."}],"status":"draft","variants":[{"id":"emergency-access-manual-validation","title":"Планова перевірка з ручним розбором сигналів","description":"Адміністратор виконує контрольний вхід за процедурою, а відповідальна команда вручну звіряє журнал і сповіщення.","best_for":["Невелика команда з окремим відповідальним за моніторинг та одним середовищем ідентичності."],"example":"Під час квартальної перевірки адміністратор підтвердив вхід і тестову дію. Черговий побачив узгоджений сигнал у журналі, звірив одержувачів сповіщення й зафіксував результат без копіювання секрету до задачі.","requirements":["Є погоджений календар перевірки, інструкція та працівник, який незалежно підтверджує сигнал."],"implementation_methods":["Створювати повторювану задачу PlanFix із датою перевірки, відповідальними, контрольним списком і посиланням на журнал.","Перед запланованим тестом сповіщати команду моніторингу окремим погодженим каналом.","Зберігати результат і винятки без значень облікових даних."],"complexity":"medium","hours_min":18,"hours_max":36,"pricing_modifiers":[],"limitations":["Журнали перевіряють вручну; невідомий сигнал потребує термінового ручного розбору."]},{"id":"emergency-access-integrated-monitoring","title":"Подієве сповіщення та контроль тестів","description":"Моніторинг передає сигнал входу у погоджений маршрут, а планові перевірки контролюють фактичне сповіщення та післяподієве рішення.","best_for":["Кілька середовищ або чергова команда з доступними журналами, автоматичними сповіщеннями та погодженим моніторингом."],"example":"Журнал Entra зафіксував використання аварійного запису. Інтеграція створила термінову задачу з ID події, часом і посиланням на джерело. Черговий класифікував сигнал як санкціоновану аварію, перевірив журнал дій і зафіксував рішення.","requirements":["Підтверджений канал доставки журналів, одержувачі сигналу, унікальний ID події та тестовий маршрут."],"implementation_methods":["Читати тільки погоджені поля журналу; не передавати пароль, код MFA чи надлишкові персональні дані.","Створювати одну задачу на унікальний ID входу й перевіряти доставку та повторні події.","Зв'язувати планові тести, журнали сигналу, післяподієве рішення й відкриті заходи."],"complexity":"high","hours_min":36,"hours_max":72,"pricing_modifiers":[],"limitations":["Конкретний API, затримка журналу та повнота подій залежать від IAM і моніторингу; це перевіряють перед підключенням."]}],"dependencies":[{"type":"related","target_id":"AUT-0086","reason":"Періодичний перегляд оцінює багато чинних доступів; ця картка перевіряє спеціально підготовлені аварійні записи, працездатність входу й реакцію на кожне використання."},{"type":"related","target_id":"AUT-0146","reason":"Тимчасовий доступ має обмежений строк і перевірене відкликання; аварійний запис є постійним резервом і потребує тесту та моніторингу."},{"type":"related","target_id":"AUT-0087","reason":"Реагування на інцидент безпеки захищає ресурси після підтвердженої події; ця картка запускає перевірку від сигналу аварійного облікового запису й звіряє його призначення."}],"configurator_questions":[{"id":"emergency-access-multiple-environments","question":"Чи потрібно вести аварійні записи для кількох окремих середовищ?","help_text":"Погодьте власника, джерело журналів, чергу сповіщень і процедуру для кожного середовища.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Додати маршрути, ролі та звірку сигналів для кількох ізольованих середовищ."}]},{"id":"emergency-access-log-integration","question":"Чи потрібно автоматично створювати випадок з журналу входу?","help_text":"Перевірте API або шлюз журналів, унікальний ID події, затримку доставки та підтвердження сигналу.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Підключити журнал входу, захист від повторів, маршрут терміновості та контроль доставки."}]}]},{"schema_version":1,"id":"AUT-0465","slug":"risk-based-critical-medical-device-supplier-audit","title":"Планування та контроль аудиту критичного постачальника медичних виробів","summary":"Виробник планує ризик-орієнтовані аудити критичних постачальників і зберігає перевірний зв’язок між планом, доказами, висновками та подальшими діями.","problem":"Плани й звіти аудитів постачальників розпорошені між календарями, поштою та папками. Команда не бачить, чому обрала постачальника, чи охопив аудит потрібні процеси та чи доступні записи для наступного перегляду.","outcome":"Для кожного запланованого аудиту є обґрунтований пріоритет, погоджені межі й критерії, кваліфіковані учасники, збережені докази та звіт із контрольованими подальшими рішеннями.","category":"production","subcategory":"quality-control","roles":["procurement-specialist","operations-manager","owner"],"industries":["healthcare","manufacturing"],"triggers":["Настав строк затвердженого аудиту постачальника критичного продукту або процесу.","Новий ризик, зміна постачальника чи повторні проблеми потребують переглянути пріоритет аудиту."],"workflow_steps":["Визначити постачальника, продукцію або аутсорсинговий процес, пов’язаний продукт і відповідального за програму аудиту.","Застосувати затверджені критерії ризику й результативності постачальника; записати причину вибору та межі аудиту.","Погодити мету, критерії, майданчик або формат, дату, команду та компетентність аудиторів; перевірити незалежність, коли вона потрібна.","Надіслати погоджений план постачальнику та зібрати лише необхідні попередні записи в сховищі з відповідними правами.","Провести аудит за затвердженим планом; фіксувати фактичні докази, вибірки та посилання на контрольовані записи.","Звірити факти з критеріями, надати постачальнику можливість уточнити фактичні помилки й випустити контрольований звіт.","Призначити власників і строки подальших дій; передати конкретну невідповідність до окремого процесу коригувальних дій постачальника.","Уповноважений фахівець оцінює завершення, ефективність і потребу змінити статус чи частоту контролю постачальника; зберегти рішення та записи за погодженим строком."],"requirements":["Визначені критерії критичності, пріоритету й частоти аудиту, власник програми та повноваження щодо статусу постачальника.","Є актуальні дані про продукцію, закупівлі, скарги, невідповідності та попередні оцінки в авторитетних системах.","Визначені компетентні аудитори, доступ до записів, правила конфіденційності й контрольоване сховище звітів.","Затверджені межі аудиту, критерії, формат звіту, строки відповіді та маршрут подальших дій."],"limitations":["FDA вказує, що за QMSR, чинним із 2 лютого 2026 року, інспектори можуть переглядати звіти аудитів постачальників. Це твердження стосується продукції під наглядом FDA.","MDSAP Audit Approach є методичним документом програми для медичних виробів і юрисдикцій-учасниць; він не встановлює універсального календаря аудиту для всіх постачальників.","PlanFix може координувати план, задачі, строки й відповідальних. Він не проводить аудит, не надає кваліфікацію аудитора та не є сховищем доказів без окремого аналізу доступу й конфіденційності.","Оцінка не включає проведення аудиту, відрядження, зовнішніх аудиторів, юридичний висновок чи сертифікацію; попередня."],"problems":["аудити постачальників прострочуються","звіти аудитів постачальників важко знайти","немає контролю аудиту критичного постачальника"],"synonyms":["аудит постачальника медичних виробів","перевірка постачальника медичних виробів","аудит критичного постачальника"],"search_queries":["як планувати аудит критичного постачальника медичних виробів","де контролювати звіти та висновки аудиту постачальника","як не пропустити повторний аудит виробника медичного обладнання"],"sources":[{"type":"vendor_documentation","title":"FDA: Quality Management System Regulation — Frequently Asked Questions","url":"https://www.fda.gov/medical-devices/quality-management-system-regulation-qmsr/quality-management-system-regulation-frequently-asked-questions","checked_at":"2026-10-09","supports":"Пункти 7–8 пояснюють, що з 2 лютого 2026 року FDA може переглядати записи системи якості, включно зі звітами аудитів постачальників. Це стосується інспекцій FDA та медичних виробів у її юрисдикції."},{"type":"vendor_documentation","title":"FDA: MDSAP Audit Approach, Chapter 7 — Purchasing","url":"https://www.fda.gov/media/157947/download","checked_at":"2026-10-09","supports":"Завдання 2 розділу закупівель описує вибір файлу оцінювання постачальника для аудиту та пріоритет за ризиком; наступні завдання розглядають критерії вибору, оцінювання й повторного оцінювання. Це методика MDSAP, а не універсальна вимога до всіх компаній."},{"type":"vendor_documentation","title":"PlanFix: Tasks","url":"https://planfix.com/help/Tasks","checked_at":"2026-10-09","supports":"Тип задачі може мати власні поля, статуси та сценарії. Це підтверджує можливість координувати внутрішній план і строки після налаштування; не підтверджує проведення аудиту чи керування регуляторними записами."},{"type":"inferred_pattern","title":"Робоча модель координації аудиту постачальника","supports":"Структуру плану, ролей, доказів, звіту та наступного рішення потрібно узгодити з системою якості, ризиками й юрисдикціями конкретного виробника. Оцінки годин є проєктними гіпотезами для аудиту."}],"status":"draft","variants":[{"id":"supplier-audit-coordination","title":"Координація аудиту та контрольованих записів","description":"Команда веде календар, межі, учасників і статус звіту, а докази зберігає у чинному контрольованому сховищі.","best_for":["Один майданчик і обмежена кількість аудитів, де записи вже мають затверджене сховище."],"example":"Після перегляду повторних невідповідностей власник програми призначив аудит постачальника стерильного компонента. Задача містила обґрунтування пріоритету, план, відповідальних і посилання на звіт у контрольованому сховищі.","requirements":["Є затверджена програма аудитів, критерії ризику й доступне контрольоване сховище."],"implementation_methods":["Налаштувати в PlanFix тип задачі з постачальником, обсягом, ризиком, строками, аудиторами, статусом звіту та посиланням на сховище.","Створювати повторну задачу за погодженою датою; прострочення й відкриті висновки передавати власнику програми.","Зберігати затверджений план, звіт і докази у контрольованій системі якості; у PlanFix залишати лише необхідні посилання."],"complexity":"medium","hours_min":24,"hours_max":48,"pricing_modifiers":[],"limitations":["Збір аудиторських доказів, висновки й погодження виконують фахівці; інтеграції зі сховищем не включені."]},{"id":"supplier-audit-risk-program","title":"Ризик-орієнтована програма для кількох майданчиків","description":"Дані оцінювання, невідповідностей і графіків пов’язують у звітність; маршрути й права перевіряють для кожного джерела.","best_for":["Кілька майданчиків, багато критичних постачальників і наявні цифрові джерела оцінок та звітів."],"example":"Якість оновила пріоритет постачальника після повторної невідповідності. Інтеграція сформувала проєкт задачі аудиту з джерельними ID, а власник підтвердив межі, аудитора та календар перед надсиланням плану.","requirements":["Джерела мають стабільні ID, узгоджені поля ризику, API або експорт, власників даних і погоджений контроль доступу."],"implementation_methods":["Перевірити джерела оцінок, закупівель і якості; узгодити правила зіставлення постачальників та журнал змін.","Автоматизувати чернетки задач і нагадування, залишивши затвердження вибору, меж і висновків за фахівцем.","Перевірити права на звіти, повторні записи, відмови інтеграції та повноту посилань на докази."],"complexity":"high","hours_min":48,"hours_max":96,"pricing_modifiers":[],"limitations":["Складність інтеграції та права на сторонні аудиторські записи перевіряють окремо; автоматизоване рішення про відповідність не передбачене."]}],"dependencies":[{"type":"related","target_id":"AUT-0369","reason":"AUT-0369 перевіряє допуск постачальника до конкретної закупівлі; ця картка планує аудит і зберігає його докази та звіт."},{"type":"related","target_id":"AUT-0437","reason":"AUT-0437 контролює відповідь на конкретний дефект і план коригувальних дій; ця картка охоплює аудит, а окремі висновки передає туди для подальшої обробки."}],"configurator_questions":[{"id":"supplier-audit-multiple-sites","question":"Чи потрібно координувати аудити для кількох майданчиків?","help_text":"Кількість майданчиків впливає на календарі, ролі, звітність і права доступу.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Додати окремі маршрути, календарі й звітність для кількох майданчиків."}]},{"id":"supplier-audit-source-integration","question":"Чи потрібно отримувати оцінки або записи аудиту з ERP/QMS?","help_text":"Потрібні системи, стабільні ID, доступні поля та правила обробки змін.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Додати одне погоджене джерело, зіставлення записів і перевірку обміну."}]}]},{"schema_version":1,"id":"AUT-0466","slug":"medical-device-gudid-record-submission-control","title":"Підготовка й контроль запису медичного виробу для GUDID","summary":"Власник даних перевіряє ідентифікатор та атрибути медичного виробу, погоджує подання до GUDID і зберігає підтвердження прийняття запису.","problem":"Дані про виріб, версію моделі та маркування надходять із різних систем. Через це запис GUDID може бути неповним або не збігатися із затвердженим маркуванням, а команда не має перевірного підтвердження подання.","outcome":"Кожне нове або змінене подання має джерела даних, узгоджений DI, відповідального labeler, погоджену версію запису, перевірений результат передачі та журнал виправлень.","category":"production","subcategory":"quality-control","roles":["operations-manager","technician","owner"],"industries":["healthcare","manufacturing"],"triggers":["Labeler готує новий запис DI для виробу або пакування, що підпадає під UDI Rule FDA.","Зміна моделі, атрибутів чи маркування вимагає переглянути наявний запис GUDID."],"workflow_steps":["Підтвердити роль labeler, ринок збуту, застосовні правила, винятки та відповідального за запис; не припускати застосовність FDA до інших юрисдикцій.","Зв’язати затверджені дані про модель і пакування з ідентифікатором DI та джерелом кожного потрібного атрибута.","Звірити назву, версію, тип пакування, компанію та інші поля з актуальною таблицею елементів GUDID; відсутні або суперечливі значення передати власникам джерел.","Перевірити відповідність запису затвердженому маркуванню та вимогам уповноваженим фахівцем; не генерувати DI без акредитованого issuing agency.","Обрати ручний вебзастосунок для поодинокого DI або погоджене подання HL7 SPL через FDA Electronic Submissions Gateway для масового пакета; для SPL підтвердити облікові записи й завершене тестування.","Передати погоджену версію, зафіксувати контрольний ідентифікатор, файл або квитанцію та прийнятий чи відхилений статус.","Для відхиленого запису створити контрольоване виправлення, повторно перевірити зміни й не вважати задачу завершеною за фактом надсилання.","Звірити опублікований DI у відкритому AccessGUDID або джерельному підтвердженні, зберегти дату та версію результату; зберігати PI у виробничому обліку, а не в GUDID."],"requirements":["Визначені labeler, ринки, застосовність UDI Rule, призначені ролі GUDID та уповноважений reviewer.","Є затверджені модель і маркування, DI від відповідного issuing agency та авторитетні джерела потрібних атрибутів.","Актуальні елементи даних і правила перевірки доступні для потрібної версії запису.","Для масового HL7 SPL подання налаштовані акаунти FDA ESG і GUDID та завершені потрібні випробування."],"limitations":["FDA вимагає UDI на маркуванні й подання даних до GUDID для виробів у сфері UDI Rule з урахуванням застосовних винятків та альтернатив; не переносити це на всі ринки.","GUDID містить Device Identifier (DI), але не Production Identifier (PI). Партію, серійний номер, дату виготовлення та строк придатності ведуть у відповідних виробничих і логістичних записах.","FDA описує ручне внесення поодиноких DI та пакетне подання HL7 SPL через ESG. Це не означає, що GUDID надає звичайний API або що будь-яка інтеграція вже доступна.","PlanFix може координувати власників, строки, погодження та посилання на контрольовані записи; він не є GUDID, issuing agency чи авторитетною системою маркування.","Години попередні. Юридична класифікація, вибір DI, точність маркування та схвалення запису залишаються відповідальністю фахівців."],"problems":["як підготувати і перевірити запис виробу для GUDID","як контролювати подання UDI до бази FDA після зміни моделі","як знайти помилку в даних медичного пристрою перед GUDID"],"synonyms":["GUDID submission","UDI device identifier record","FDA GUDID record","подання DI до GUDID","ідентифікатор виробу FDA"],"search_queries":["як контролювати подання даних медичного виробу до GUDID після зміни етикетки","як звірити DI пристрою з його маркуванням та записом FDA","як підтвердити прийняття пакета HL7 SPL для медичних виробів"],"sources":[{"type":"vendor_documentation","title":"FDA: UDI Basics","url":"https://www.fda.gov/medical-devices/unique-device-identification-system-udi-system/udi-basics","checked_at":"2026-10-09","supports":"FDA описує DI як обов’язкову фіксовану частину UDI, PI як умовну змінну частину; GUDID містить тільки DI. Вимоги стосуються labeler і виробів у сфері правила FDA з винятками, а не кожного ринку."},{"type":"vendor_documentation","title":"FDA: Submit Data to GUDID","url":"https://www.fda.gov/medical-devices/global-unique-device-identification-database-gudid/submit-data-gudid","checked_at":"2026-10-09","supports":"Офіційна сторінка описує ручне внесення одиничних DI через GUDID web application та пакетні файли HL7 SPL через FDA Electronic Submissions Gateway. Для SPL потрібні облікові записи й тестування."},{"type":"vendor_documentation","title":"FDA: Prepare for GUDID","url":"https://www.fda.gov/medical-devices/global-unique-device-identification-database-gudid/prepare-gudid","checked_at":"2026-10-09","supports":"FDA радить організувати й перевірити дані, визначити ролі, зібрати атрибути та вибрати варіант подання; підготовка потребує координації даних у кількох системах."},{"type":"vendor_documentation","title":"PlanFix: Tasks","url":"https://planfix.com/help/Tasks","checked_at":"2026-10-09","supports":"Поля, статуси й сценарії задач можуть координувати внутрішні погодження та строки після конфігурації. Документація не підтверджує прямої інтеграції PlanFix із GUDID або FDA ESG."},{"type":"inferred_pattern","title":"Редакційна модель контролю подання GUDID","supports":"Зіставлення джерел, маршрут погодження, перевірка квитанції та збереження версій — проєктна модель для аудиту. Оцінки не підтверджені впровадженням клієнта."}],"status":"draft","variants":[{"id":"gudid-single-record-review","title":"Ручне подання та перевірка одиничних записів","description":"Фахівець узгоджує поля з контрольованими джерелами, вносить DI через GUDID web application та перевіряє результат.","best_for":["Небагато нових чи змінених DI та можливість вручну працювати з порталом GUDID."],"example":"Власник моделі надав затверджені характеристики й DI від issuing agency. Reviewer знайшов відсутнє значення пакування, повернув запис на уточнення, а після ручного подання зберіг підтвердження й звірив публічний запис.","requirements":["Є користувачі GUDID, затверджені дані та reviewer, уповноважений підтвердити запис."],"implementation_methods":["Створювати задачу з DI, джерелами атрибутів, версією запису й контрольним списком для reviewer.","Передавати затверджене значення до GUDID web application уповноваженим labeler-користувачем.","Зберігати квитанцію, дату й результат перевірки публічного DI; PI залишати в системі партій або серійного обліку."],"complexity":"medium","hours_min":20,"hours_max":40,"pricing_modifiers":[],"limitations":["Внесення виконує людина; автоматичне створення або подання DI не включене."]},{"id":"gudid-bulk-spl-review","title":"Пакетне подання HL7 SPL із контрольованою звіркою","description":"Команда формує узгоджений набір записів із джерел даних, готує та перевіряє SPL і підтверджує результат через FDA ESG.","best_for":["Багато DI, стабільні джерела даних, уповноважена команда й налаштовані акаунти та тестування FDA ESG."],"example":"Зміна лінійки торкнулася кількох моделей. Інтеграційна команда зіставила DI та атрибути з системи життєвого циклу виробу, відхилила неповні рядки, а reviewer погодив валідований пакет SPL до передачі через ESG.","requirements":["Для ESG завершені реєстрація й тестування; підтверджено формат даних, унікальні DI, джерельні ID та порядок повторної передачі."],"implementation_methods":["Зіставити затверджений product master із таблицею полів GUDID і перевірити походження значень.","Сформувати SPL за вимогами FDA, виконати тестування та передати пакет тільки після ручного погодження.","Зіставити результат ESG із кожним DI, повернути відхилені записи на виправлення й зберегти версію файлу та квитанції."],"complexity":"high","hours_min":48,"hours_max":96,"pricing_modifiers":[],"limitations":["Вимагає окремого тестованого контуру FDA ESG; схема та правила подання мають відповідати актуальним вимогам FDA."]}],"dependencies":[{"type":"related","target_id":"AUT-0186","reason":"AUT-0186 контролює внутрішній довідник сканованих штрихкодів та одиниць товару. Ця картка готує DI-запис до GUDID і не виводить PI з товарного штрихкоду."},{"type":"related","target_id":"AUT-0263","reason":"AUT-0263 веде регуляторну оцінку повідомлення після інциденту з медичним виробом. Ця картка забезпечує точність і підтвердження запису DI до виникнення такого випадку."}],"configurator_questions":[{"id":"gudid-source-systems","question":"Чи надходять дані атрибутів із кількох систем?","help_text":"Визначте, де зберігаються модель, маркування, пакування, DI та значення полів GUDID.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Додати зіставлення джерел, правила пріоритету та перевірку конфліктів."}]},{"id":"gudid-multiple-labelers","question":"Чи потрібно координувати записи кількох юридичних осіб-labeler?","help_text":"Потрібні окремі акаунти, ролі, власники DI та погодження для кожної організації.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Додати маршрути, розмежування власників та окреме підтвердження для кожного labeler."}]}]},{"schema_version":1,"id":"AUT-0467","slug":"positive-pay-check-exception-review","title":"Розгляд винятків Positive Pay для виданих чеків","summary":"Фінансист перевіряє чекові винятки банку за реєстром виданих чеків і передає своєчасне погоджене рішення уповноваженому користувачу банку.","problem":"Банк показує чек, який не збігся з реєстром виданих чеків, але сповіщення губиться або рішення приймають без перевірки рахунку, номера, суми, отримувача та підстави виплати.","outcome":"Кожний виняток має джерельний запис, причину розбіжності, доказ перевірки, уповноваженого погоджувача, передане до банку рішення та підтверджений результат до банківського строку.","category":"finance","subcategory":"payments","roles":["finance-specialist","owner","operations-manager"],"industries":["manufacturing","wholesale","professional-services","cross-industry"],"triggers":["Банк надіслав Positive Pay виняток щодо чека, якого немає у файлі видачі або чиї реквізити не збіглися.","Потрібно перевірити повторний номер, суму, статус скасування, дату чи ім’я отримувача до рішення банку."],"workflow_steps":["Отримати виняток із банківського порталу або погодженого каналу та записати рахунок, номер чека, суму, дату, отримувача, причину й строк рішення.","Зіставити його з авторитетним реєстром випущених і скасованих чеків, затвердженим рахунком постачальника, рахунком-фактурою та документом погодження.","Якщо доступне зображення, перевірити лицьовий і зворотний бік, отримувача, індосамент і ознаки зміни; невідомий, дубльований або змінений чек передати на ескалацію.","Визначити маршрут: підтверджений чек, виправлення файлу видачі, перевірка скасування або потенційне шахрайство. Не створювати оплату з задачі й не змінювати банківський запис автоматично.","За розділенням обов’язків фінансовий reviewer перевіряє висновок, а окремий уповноважений користувач ухвалює `pay` або `return` у порталі банку до фактичного строку.","Зафіксувати рішення, підставу, особу, час і банківське підтвердження; якщо рішення не передано, негайно ескалувати за фактичною політикою банку.","Після обробки звірити результат із банківським звітом і реєстром видачі; несподіване проведення повідомити банку й передати до окремого процесу реагування на платіжне шахрайство.","Зберігати лише потрібні метадані й захищені посилання на зображення; не копіювати повний номер рахунку або банківські облікові дані в загальні задачі."],"requirements":["Банк пропонує Positive Pay для рахунку та повідомляє чинні формати реєстру, типи винятків, строки й наслідки відсутності рішення.","Є повний і актуальний реєстр чеків, ідентифікатори рахунків, одержувачі, суми, причини видачі та статуси скасування.","Визначені різні ролі підготовки, перевірки та банківського рішення; доступ до зображень і фінансових даних обмежено.","Погоджені порядок перевірки підозрілих винятків, резервний контакт банку, часовий пояс та канал ескалації до cut-off."],"limitations":["Positive Pay, payee matching, типи винятків, строки й результат бездіяльності залежать від конкретного банку, рахунку та договору; не задавати універсальне рішення за замовчуванням.","Банк зіставляє представлені чеки з реєстром клієнта й показує невідповідності; фінансовий фахівець має визначити, чи платити або повертати чек.","PlanFix може координувати відповідальних, дедлайн, докази й ескалацію. Остаточне рішення виконує уповноважений користувач у банківському каналі.","Не підключає банківський портал без окремого підтвердженого інтерфейсу й правил безпеки; не гарантує відшкодування збитків.","Години попередні; доступність функцій, обсяг чеків, кількість рахунків і спосіб передавання даних потрібно перевірити з банком."],"problems":["як перевіряти підозрілі чеки у Positive Pay до списання з рахунку","банк надіслав виняток щодо чека кому його погодити і до якого строку","як звірити чек який банк не знайшов у реєстрі виданих оплат"],"synonyms":["positive pay exception","check issue file","payee positive pay","виняток перевірки чека","перевірка виданих чеків у банку"],"search_queries":["як погоджувати винятки Positive Pay щодо суми або отримувача чека","як вчасно передати банку рішення оплатити чи повернути підозрілий чек","як звірити представлений банку чек із реєстром виданих оплат"],"sources":[{"type":"vendor_documentation","title":"U.S. Bank: Cash Risk Management Solutions","url":"https://www.usbank.com/corporate-and-commercial-banking/solutions/liquidity-and-investments/cash-risk-management.html","checked_at":"2026-10-09","supports":"U.S. Bank описує електронне зіставлення представлених чеків із файлом виданих інструментів; невідповідності стають винятками, щодо яких клієнт приймає рішення оплатити або повернути. Умови стосуються конкретної пропозиції банку."},{"type":"vendor_documentation","title":"U.S. Bank: Fraud Prevention Checklist","url":"https://www.usbank.com/corporate-and-commercial-banking/insights/risk/mitigation/fraud-prevention-checklist.html","checked_at":"2026-10-09","supports":"Банк радить щодня переглядати чекові й payee-винятки та приймати рішення. Перелік є описом його продукту, а не універсальним SLA для всіх банків."},{"type":"vendor_documentation","title":"Bank of America: Check Positive Pay Fact Sheet","url":"https://images.em.bankofamerica.com/GTS/Payments/Check_Positive_Pay_Fact_Sheet.PDF","checked_at":"2026-10-09","supports":"Описує зіставлення номера, суми й за доступного сервісу payee, перегляд зображень, ролі decision-maker та подання рішення до банківського дедлайну. Список функцій залежить від підписаної послуги."},{"type":"vendor_documentation","title":"PlanFix: Tasks","url":"https://planfix.com/help/Tasks","checked_at":"2026-10-09","supports":"Налаштований тип задачі може мати власні поля, статуси та автоматизовані сценарії. Це підтверджує внутрішню координацію винятків, а не з’єднання з порталом банку."},{"type":"inferred_pattern","title":"Редакційна модель незалежної перевірки чекових винятків","supports":"Зіставлення реєстру, розподіл обов’язків, ескалація та попередні трудовитрати є проєктною моделлю для аудиту конкретного банку й ERP."}],"status":"draft","variants":[{"id":"positive-pay-manual-exception-control","title":"Ручний розгляд із банківським рішенням","description":"Фінансист приймає сповіщення, звіряє його з ERP і доказами, а уповноважений працівник вносить рішення в портал банку.","best_for":["Один банк і небагато винятків, які можна своєчасно перевірити вручну."],"example":"Банк знайшов чек на 18 400 USD без збігу в issue file. Фінансист перевірив номер, суму й отримувача за затвердженим рахунком, не знайшов дозволу на видачу й передав підтверджене рішення `return` авторизованому користувачу до банківського строку.","requirements":["Є доступ до порталу банку, актуальний реєстр чеків і резервний відповідальний на час відсутності основного."],"implementation_methods":["Вести задачу з банківським ID винятку, рахунком, номером чека, сумою, причиною та часом cut-off.","Додати контрольний список джерел звірки й окремі ролі reviewer та банківського approver.","Зберігати обране рішення, час передачі й ідентифікатор банківського підтвердження; звірити його наступним звітом."],"complexity":"medium","hours_min":16,"hours_max":32,"pricing_modifiers":[],"limitations":["Користувачі вносять і перевіряють винятки вручну; у разі високого обсягу потрібен додатковий контроль зміни."]},{"id":"positive-pay-integrated-issue-and-exception-control","title":"Передавання issue file та маршрутизація винятків","description":"Погоджений файл видачі передається банку через підтриманий канал, а винятки формують чергу з дедлайном і підтвердженням.","best_for":["Кілька рахунків або регулярний обсяг чеків за наявності банківського формату, інтеграційного каналу й стабільного джерела даних."],"example":"ERP передала денний issue file. Контроль відхилив рядок без рахунку, а два bank exceptions створили окремі задачі з банківським cut-off. Задачі не виставили рішення автоматично; фінансові approvers внесли його в банку й підтвердили статус.","requirements":["Банк підтвердив канал передачі, формат issue/paid file, календар, дедлайни й призначені користувацькі права."],"implementation_methods":["Зіставити ERP-файл із банківським форматом та перевірити кількість рядків, суми, дублі й контрольні totals перед відправленням.","Приймати винятки за унікальним ID, ставити cut-off і маршрутизувати їх за рахунком та сумою без автоматичного рішення pay/return.","Повторно читати банківський статус та звіряти його з ERP; помилки доставки, запізнення й невідомі статуси блокувати для ручного розбору."],"complexity":"high","hours_min":32,"hours_max":64,"pricing_modifiers":[],"limitations":["Технічний канал, SLA, формати й можливість читати exceptions залежать від банку та мають бути перевірені до оцінки інтеграції."]}],"dependencies":[{"type":"related","target_id":"AUT-0406","reason":"AUT-0406 розбирає сторнування чека, який уже видали. Positive Pay починається з винятку чека, пред’явленого банку, і рішення до оплати."},{"type":"related","target_id":"AUT-0116","reason":"Звірка банківського рахунку пояснює рухи після проведення; Positive Pay перевіряє виняток до рішення банку щодо пред’явленого чека."}],"configurator_questions":[{"id":"positive-pay-multiple-accounts","question":"Чи потрібно вести винятки для кількох банківських рахунків?","help_text":"Потрібно звірити окремі ролі, часові пояси, календарі та дедлайни кожного рахунку.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":8,"add_hours_max":16,"assumption":"Додати конфігурацію рахунків, власників, дедлайнів і звітність за кожним банківським каналом."}]},{"id":"positive-pay-file-integration","question":"Чи потрібно передавати issue file та отримувати винятки автоматично?","help_text":"Спочатку підтвердьте з банком формат, підтриманий канал, тестування й права користувачів.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":12,"add_hours_max":24,"assumption":"Додати одну погоджену інтеграцію файлів, перевірку totals, повторів і статусів доставки."}]}]},{"schema_version":1,"id":"AUT-0468","slug":"employee-compensation-review-followup","title":"Контроль обіцяного перегляду умов оплати працівника","summary":"Керівник отримує нагадування про індивідуальний перегляд оплати, фіксує рішення та наступну дату з доступом лише для уповноважених осіб.","problem":"Керівник обіцяв повернутися до умов оплати через кілька місяців, але забув дату. Працівник чекає, а команда не бачить, чи перегляд відбувся та хто має ухвалити рішення.","outcome":"Кожний запланований перегляд має працівника, відповідального, строк, зафіксоване рішення та наступну дату. Прострочення видно керівнику; погоджену зміну передають окремому кадровому процесу.","category":"hr","subcategory":"workforce","roles":["owner","hr-specialist","operations-manager"],"industries":["cross-industry","e-commerce","professional-services"],"triggers":["Наближається індивідуальна дата перегляду оплати, визначена в домовленості з працівником.","Керівник погодив нову дату після завершення попереднього перегляду."],"workflow_steps":["Пов’язати перегляд із працівником, чинними умовами, обіцяною датою та відповідальним; перевірити, чи вже існує відкритий перегляд цієї домовленості.","Надати доступ лише працівникам кадрової служби та уповноваженим керівникам; перевірити його після зміни підпорядкування.","До строку нагадати відповідальному й запросити обґрунтування пропозиції; прострочений перегляд показати в окремій черзі.","Передати конкретну пропозицію погоджувачу. Зафіксувати рішення: змінити умови, залишити чинні або перенести перегляд із причиною та новою датою.","Зберегти підтвердження повідомлення працівника та наступну дату перегляду; рішення про зміну передати в процес введення умов із датою чинності.","Закрити перегляд після фіксації рішення й наступного кроку; зберегти попередні домовленості без перезаписування їх історії."],"requirements":["Є узгоджені індивідуальні дати, власник перегляду та уповноважений погоджувач.","Визначено джерело чинних умов, правила доступу й порядок повідомлення працівника.","Кадрові та фінансові дані зберігаються в погодженому захищеному контурі."],"limitations":["Перегляд не гарантує підвищення та не визначає ринковий рівень зарплати автоматично.","Нарахування зарплати, виплата й фактичне введення нової ставки потребують окремих процесів.","Кейс PlanFix є історичною практикою; доступи й сценарії перевіряють у цільовому акаунті перед реалізацією."],"problems":["керівник забуває обіцяний перегляд зарплати","як не пропустити індивідуальну дату перегляду оплати","працівник чекає рішення про зарплату"],"synonyms":["ревізія окладу","перегляд зарплатної політики","обіцяне підвищення","індивідуальний перегляд винагороди"],"search_queries":["як не забути обіцяний працівнику перегляд зарплати","як нагадати керівнику про дату перегляду оплати","як зафіксувати рішення залишити зарплату до наступного перегляду"],"sources":[{"type":"public_case","title":"PlanFix: облік зарплатних політик у Alisa.ua","url":"https://planfix.ru/blog/a-u-vas-kak-organizovat-uchyot-zarplatnyh-politik-v-planfikse/","checked_at":"2026-10-09","supports":"Кейс від 26.11.2020 описує індивідуальні політики, зв’язок із контактом працівника, доступ керівника до підлеглих, нагадування про прострочення та погодження з CEO. Автор прямо зазначає, що щомісячний розрахунок зарплати не автоматизовано."},{"type":"inferred_pattern","title":"Редакційна модель завершення індивідуального перегляду","supports":"Контроль повторів, рішення залишити умови або перенести перегляд, підтвердження повідомлення, передавання кадрової зміни та оцінки годин є гіпотезами для аудиту. Це не підтверджений кейс CRMCUSTOMS."}],"status":"draft","variants":[{"id":"compensation-review-reminder","title":"Нагадування та рішення власника","description":"Індивідуальні дати й прострочення ведуть у задачах; власник фіксує рішення та наступний перегляд.","best_for":["Невелика команда з одним погоджувачем і ручним внесенням дат."],"example":"Після випробувального строку керівник обіцяв обговорити оплату в грудні. Нагадування повернуло домовленість у його чергу; він залишив умови, пояснив рішення працівнику й визначив наступний перегляд у березні.","implementation_methods":["Налаштувати шаблон задачі з працівником, строком, відповідальним і рішенням.","Показати прострочення у фільтрі та налаштувати нагадування.","Зберігати дату наступного перегляду й посилання на попередню домовленість."],"complexity":"low","hours_min":10,"hours_max":20,"requirements":["Власник вручну підтверджує рішення й наступну дату."],"limitations":["Автоматичний імпорт кадрових даних і командне бюджетування не включені."],"pricing_modifiers":[]},{"id":"compensation-review-managed","title":"Перегляд із погодженням та ескалацією","description":"Керівник готує обґрунтування, погоджувач ухвалює рішення, а прострочення й повернення контролюються окремими статусами.","best_for":["Команда з кадровим координатором і розмежуванням доступу між керівниками."],"example":"Координатор отримав прострочений перегляд після зміни керівника. Він передав відповідальність новому керівнику, перевірив доступ, а власник повернув неповне обґрунтування. Після погодження зміни створили пов’язану кадрову задачу.","implementation_methods":["Налаштувати статуси підготовки, погодження, повернення й завершення з фіксацією автора рішення.","Ескалувати прострочення координатору та зберігати історію зміни відповідального.","Передавати погоджену зміну в кадровий процес і пов’язувати її з переглядом."],"complexity":"medium","hours_min":20,"hours_max":40,"requirements":["Визначено координатора, матрицю доступу та правила повернення на доопрацювання."],"limitations":["Рішення ухвалює людина; автоматичний розрахунок ринкової ставки не включений."],"pricing_modifiers":[]}],"dependencies":[{"type":"related","target_id":"AUT-0140","reason":"Після рішення змінити оплату AUT-0140 вводить погоджені умови з датою чинності. Ця картка контролює своєчасність самого перегляду, включно з рішенням залишити умови."},{"type":"related","target_id":"AUT-0224","reason":"AUT-0224 погоджує сукупний бюджет командного циклу. Індивідуальна обіцяна дата може настати поза таким циклом; ця картка не розподіляє командний бюджет."}],"configurator_questions":[{"id":"compensation-review-management-changes","question":"Чи потрібно передавати відкриті перегляди після зміни керівника?","help_text":"Визначте джерело підпорядкування та хто підтверджує нові права доступу.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":6,"add_hours_max":12,"assumption":"Додати передачу відповідальності та перевірку доступу до відкритих переглядів."}]},{"id":"compensation-review-hr-import","question":"Чи потрібно імпортувати індивідуальні дати з кадрової системи?","help_text":"Потрібні стабільні ID працівників і правило обробки змінених чи видалених домовленостей.","type":"boolean","options":[],"required":true,"show_if":null,"effects":[{"when":true,"add_hours_min":10,"add_hours_max":20,"assumption":"Додати зіставлення працівників, контроль повторного імпорту та конфліктів дат."}]}]}];
